    /**
     * Method to retrieve the Creditor via CreditorFetchOneSummary
     * @param 	summary CreditorFetchOneSummary 
     * @return 	CreditorFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Creditor getCreditor( CreditorFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "CreditorFetchOneSummary arg cannot be null" );
    	
    	Creditor entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Creditor
        	// --------------------------------------
        	CompletableFuture<Creditor> futureEntity = queryGateway.query(new FindCreditorQuery( new LoadCreditorFilter( summary.getCreditorId() ) ), ResponseTypes.instanceOf(Creditor.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Creditor with id " + summary.getCreditorId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


